import numpy as np
# W: the reference path, 4,097 values (provided)

def ito_sum(W):
    """Left-point sum: W[k] * (W[k+1] - W[k]), added up."""
    W = np.asarray(W)
    return float(np.sum(W[:-1] * np.diff(W)))

def mid_sum(W):
    """Same, with the average (W[k] + W[k+1]) / 2 as position."""
    W = np.asarray(W)
    return float(np.sum((W[:-1] + W[1:]) / 2 * np.diff(W)))

def right_sum(W):
    """Same, with W[k+1] as position."""
    W = np.asarray(W)
    return float(np.sum(W[1:] * np.diff(W)))
